const retainedChromeOwners = new WeakMap<AndroidDriver, {owner: Chromedriver; token: string; failed: boolean}>();

function requireRetainedChromeOwner(driver: AndroidDriver, context: string): Chromedriver {
  const expected = retainedChromeOwners.get(driver);
  if (!expected || expected.failed || context !== CHROMIUM_WIN ||
      driver.sessionChromedrivers[CHROMIUM_WIN] !== expected.owner ||
      expected.owner.sessionId() !== expected.token) {
    if (expected) expected.failed = true;
    throw new Error('Retained Chrome owner is unavailable or changed');
  }
  return expected.owner;
}

